27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "possible_duplicate")
73	    private Boolean possibleDuplicate;
74	
75	    @Column(name = "possible_duplicate_of")
76	    private Integer possibleDuplicateOf;
77	
78	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public LocalDate getBirthDate() {
130	        return this.birthDate;
131	    }
132	
133	    public void setBirthDate(LocalDate birthDate) {
134	        this.birthDate = birthDate;
135	    }
136	
137	    public String getCustomerCode() {
138	        return this.customerCode;
139	    }
140	
141	    public void setCustomerCode(String customerCode) {
142	        this.customerCode = customerCode;
143	    }
144	
145	    public String getHouseholdId() {
146	        return this.householdId;
147	    }
148	
149	    public void setHouseholdId(String householdId) {
150	        this.householdId = householdId;
151	    }
152	
153	    public Integer getNamesakeCount() {
154	        return this.namesakeCount;
155	    }
156	
157	    public void setNamesakeCount(Integer namesakeCount) {
158	        this.namesakeCount = namesakeCount;
159	    }
160	
161	    public Boolean getPossibleDuplicate() {
162	        return this.possibleDuplicate;
163	    }
164	
165	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
166	        this.possibleDuplicate = possibleDuplicate;
167	    }
168	
169	    public Integer getPossibleDuplicateOf() {
170	        return this.possibleDuplicateOf;
171	    }
172	
173	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
174	        this.possibleDuplicateOf = possibleDuplicateOf;
175	    }
176	
177	    protected Set<Pet> getPetsInternal() {
178	        if (this.pets == null) {
179	            this.pets = new HashSet<>();
180	        }
181	        return this.pets;
182	    }
183	
184	    protected void setPetsInternal(Set<Pet> pets) {
185	        this.pets = pets;
186	    }
187	
188	    public List<Pet> getPets() {
189	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
190	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
191	        return Collections.unmodifiableList(sortedPets);
192	    }
193	
194	    public void setPets(List<Pet> pets) {
195	        this.pets = new HashSet<>(pets);
196	    }
197	
198	    public void addPet(Pet pet) {
199	        getPetsInternal().add(pet);
200	        pet.setOwner(this);
201	    }
202	
203	    /**
204	     * Return the Pet with the given name, or null if none found for this Owner.
205	     *
206	     * @param name to test
207	     * @return true if pet name is already in use
208	     */
209	    public Pet getPet(String name) {
210	        return getPet(name, false);
211	    }
212	
213	    /**
214	     * Return the Pet with the given name, or null if none found for this Owner.
215	     *
216	     * @param name to test
217	     * @return true if pet name is already in use
218	     */
219	    public Pet getPet(String name, boolean ignoreNew) {
220	        name = name.toLowerCase();
221	        for (Pet pet : getPetsInternal()) {
222	            if (!ignoreNew || !pet.isNew()) {
223	                String compName = pet.getName();
224	                compName = compName.toLowerCase();
225	                if (compName.equals(name)) {
226	                    return pet;
227	                }
228	            }
229	        }
230	        return null;
231	    }
232	
233	    public Pet getPet(Integer petId) {
234	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
235	    }
236	
237	    @Override
238	    public String toString() {
239	        return new ToStringCreator(this)
240	
241	            .append("id", this.getId())
242	            .append("new", this.isNew())
243	            .append("lastName", this.getLastName())
244	            .append("firstName", this.getFirstName())
245	            .append("address", this.address)
246	            .append("city", this.city)
247	            .append("telephone", this.telephone)
248	            .toString();
249	    }
250	}
