69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
74	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
77	
78	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        List<OwnerDto> ownerDtos = owners.stream()
112	            .map(this::toOwnerDtoWithBulkWarning)
113	            .toList();
114	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
141	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
142	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
143	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
144	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
145	        requireDailyLimitNotReached(registrationDate);
146	        requireCityBelowCapacity(ownerFieldsDto.getCity());
147	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
148	        ownerFieldsDto.setTelephone(normalizedTelephone);
149	        if (ownerFieldsDto.getEmail() != null) {
150	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
151	        }
152	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
153	        HttpHeaders headers = new HttpHeaders();
154	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
155	        owner.setAddress(normalizedAddress);
156	        owner.setRegistrationDate(registrationDate);
157	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
158	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
159	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
160	        requireUniqueIdentity(owner);
161	        requireNoHouseholdDuplicate(owner, sharesHousehold);
162	        markPossibleDuplicate(owner, sharesHousehold);
163	        this.clinicService.saveOwner(owner);
164	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
165	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
166	            ownerMapper.toMembershipLevel(owner));
167	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
185	        this.clinicService.saveOwner(currentOwner);
186	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Transactional
191	    @Override
192	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        this.clinicService.deleteOwner(owner);
198	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner == null) {
206	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
207	        }
208	        HttpHeaders headers = new HttpHeaders();
209	        Pet pet = petMapper.toPet(petFieldsDto);
210	        owner.setId(ownerId);
211	        pet.setOwner(owner);
212	        pet.getType().setName(null);
213	        this.clinicService.savePet(pet);
214	        PetDto petDto = petMapper.toPetDto(pet);
215	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
216	            .buildAndExpand(pet.getId()).toUri());
217	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner != null) {
225	            Pet currentPet = this.clinicService.findPetById(petId);
226	            if (currentPet != null) {
227	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
228	                currentPet.setName(petFieldsDto.getName());
229	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
230	                this.clinicService.savePet(currentPet);
231	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
240	        HttpHeaders headers = new HttpHeaders();
241	        Visit visit = visitMapper.toVisit(visitFieldsDto);
242	        Pet pet = new Pet();
243	        pet.setId(petId);
244	        visit.setPet(pet);
245	        this.clinicService.saveVisit(visit);
