266	    /**
267	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
268	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
269	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
270	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The code
271	     * carries no sequence number: it is a deterministic function of the owner's region and identity.
272	     *
273	     * @param owner the owner being created, with its region-determining postcode and city populated
274	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
275	     * @return the region-and-hash customer code for the owner being created
276	     */
277	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
278	        String region = ownerMapper.toRegion(owner);
279	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
280	        return region + "-" + hash8;
281	    }
282	
283	    /**
284	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
285	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
286	     */
287	    private static String sha256Hex8(String value) {
288	        try {
289	            byte[] digest = MessageDigest.getInstance("SHA-256")
290	                .digest(value.getBytes(StandardCharsets.UTF_8));
291	            StringBuilder sb = new StringBuilder();
292	            for (byte b : digest) {
293	                sb.append(String.format("%02X", b));
294	            }
295	            return sb.substring(0, 8);
296	        }
297	        catch (NoSuchAlgorithmException e) {
298	            throw new IllegalStateException("SHA-256 not available", e);
299	        }
300	    }
301	
302	    /**
303	     * Counts the existing owners (those already persisted before this create) whose first and last
304	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
305	     * the new owner as its {@code namesakeCount} and echoed back on reads.
306	     *
307	     * @param firstName the incoming owner's first name (already validated non-blank)
308	     * @param lastName the incoming owner's last name (already validated non-blank)
309	     * @return the number of existing namesakes sharing both names case-insensitively
310	     */
311	    private int countNamesakes(String firstName, String lastName) {
312	        return (int) this.clinicService.findAllOwners().stream()
313	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
314	                && lastName.equalsIgnoreCase(existing.getLastName()))
315	            .count();
316	    }
