318	    /**
319	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
320	     * whitespace-only), so the caller can reject the request listing every offending field.
321	     */
322	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
323	        if (value == null || value.isBlank()) {
324	            missingFields.add(fieldName);
325	        }
326	    }
327	
328	    /**
329	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
330	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
331	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
332	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
333	     * {@code "+61412345678"}.
334	     *
335	     * @param telephone the raw telephone value from the request
336	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
337	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
338	     */
339	    private static String normalizeTelephone(String telephone) {
340	        String e164 = toE164(telephone);
341	        if (e164 == null) {
342	            throw new InvalidFieldValueException("telephone",
343	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
344	        }
345	        return e164;
346	    }
347	
348	    /**
349	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
350	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
351	     * owners' stored numbers when detecting duplicates.
352	     */
353	    private static String toE164(String telephone) {
354	        if (telephone == null) {
355	            return null;
356	        }
357	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
358	        String digits;
359	        if (cleaned.startsWith("+")) {
360	            digits = cleaned.substring(1);
361	        } else {
362	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
363	            digits = "61" + national;
364	        }
365	        if (!digits.matches("[0-9]{8,15}")) {
366	            return null;
367	        }
368	        if (!hasValidNationalLength(digits)) {
369	            return null;
370	        }
371	        return "+" + digits;
372	    }
373	
374	    /**
375	     * Checks the national-number length against the country code for the country codes that pin one.
376	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
377	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
378	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
379	     */
380	    private static boolean hasValidNationalLength(String digits) {
381	        if (digits.startsWith("61")) {
382	            return digits.length() - 2 == 9;
383	        }
384	        if (digits.startsWith("1")) {
385	            return digits.length() - 1 == 10;
386	        }
387	        return true;
388	    }
389	
390	    /**
391	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
392	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
393	     *
394	     * @param email the raw email value from the request (already known to be non-null)
395	     * @return the lower-cased email to be stored and returned
396	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
397	     */
398	    private static String normalizeEmail(String email) {
399	        String trimmed = email.trim();
400	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
401	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
402	        }
403	        return trimmed.toLowerCase(Locale.ROOT);
404	    }
405	
406	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
407	    private static final int MAX_OWNERS_PER_CITY = 50;
408	
409	    /**
410	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
411	     * owners, comparing city names case-insensitively. Callers reach this only once {@code city} has
412	     * been validated non-blank.
413	     *
414	     * @param city the incoming owner's city (already validated non-blank)
415	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
416	     */
417	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
418	    private static final int MAX_OWNERS_PER_DAY = 100;
419	
420	    /**
421	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
422	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
423	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
424	     * date rolled forward to a business day), so this caps the number that may be created per day.
425	     *
426	     * @param businessDay the adjusted business-day registration date of the owner being created
427	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
428	     */
429	    /**
430	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
431	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
432	     */
433	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
434	
435	    /**
436	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
437	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
438	     * owner's registration date, otherwise {@code false}.
439	     *
440	     * @param owner the owner to map
441	     * @return the owner DTO with its bulk-signup warning flag populated
442	     */
443	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
444	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
445	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
446	        return ownerDto;
447	    }
448	
449	    /**
450	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
451	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
452	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
453	     */
454	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
455	        if (registrationDate == null) {
456	            return false;
457	        }
458	        long registeredThatDay = this.clinicService.findAllOwners().stream()
459	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
460	            .count();
461	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
462	    }
463	
464	    private void requireDailyLimitNotReached(LocalDate businessDay) {
465	        long registeredThatDay = this.clinicService.findAllOwners().stream()
466	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
467	            .count();
468	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
469	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
470	        }
471	    }
472	
473	    /**
474	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
475	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
476	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
477	     * is recorded on the next business day, and every value derived from the registration date uses the
478	     * adjusted date.
479	     *
480	     * @param date the effective registration date (supplied or defaulted), never {@code null}
481	     * @return the same date, or the next Monday when {@code date} is a weekend
482	     */
483	    private static LocalDate toBusinessDay(LocalDate date) {
484	        DayOfWeek day = date.getDayOfWeek();
485	        if (day == DayOfWeek.SATURDAY) {
486	            return date.plusDays(2);
487	        }
488	        if (day == DayOfWeek.SUNDAY) {
489	            return date.plusDays(1);
490	        }
491	        return date;
492	    }
493	
494	    /** Matches a well-formed postcode: exactly four decimal digits. */
495	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
496	
497	    /**
498	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
499	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
500	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
501	     * present here and accepts any well-formed postcode.
502	     */
503	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
504	        "NSW", new int[] {2000, 2099},
505	        "VIC", new int[] {3000, 3099},
506	        "QLD", new int[] {4000, 4099});
507	
508	    /**
509	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
510	     * optional, so the request contract stays backward-compatible). When present it must be exactly
511	     * four digits and, for a city whose region is known, fall within that region's inclusive range
512	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
513	     * postcode. A malformed or out-of-range value is rejected with a 400.
514	     *
515	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
516	     * @param city the owner's city, used to look up the region whose range constrains the postcode
517	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
518	     */
519	    private void validatePostcode(String postcode, String city) {
520	        if (postcode == null) {
521	            return;
522	        }
523	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
524	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
525	        }
526	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
527	        int[] range = REGION_POSTCODES.get(region);
528	        if (range == null) {
529	            return;
530	        }
531	        int value = Integer.parseInt(postcode);
532	        if (value < range[0] || value > range[1]) {
533	            throw new InvalidFieldValueException("postcode",
534	                "Postcode must be valid for the city's region " + region);
535	        }
536	    }
537	
538	    /**
539	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
540	     * date defaults to the server date). When present it must not be later than the current server
541	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
542	     *
543	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
544	     * @throws InvalidFieldValueException if the supplied date is later than the server date
545	     */
546	    private void validateRegistrationDate(LocalDate registrationDate) {
547	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
548	            throw new InvalidFieldValueException("registrationDate",
549	                "Registration date must not be later than the current date");
550	        }
551	    }
552	
553	    private void requireCityBelowCapacity(String city) {
554	        long cityOwners = this.clinicService.findAllOwners().stream()
555	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
556	            .count();
557	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
558	            throw new CityAtCapacityException(city);
559	        }
560	    }
561	
562	    /**
563	     * Rejects the request when the incoming owner's derived {@code identityKey} exactly matches that
564	     * of any existing owner. The key ({@code normalizedTelephone + '|' + (email or empty) + '|' +
565	     * (householdId or empty)}) is the single consolidated duplicate-detection key that replaces the
566	     * former separate telephone, email and household checks. Because the telephone is part of the
567	     * key, two members of the same household (same {@code householdId}) with different telephones
568	     * have different keys and are both allowed; only an exact full-key match is a duplicate. The key
569	     * is derived identically for the incoming and existing owners via {@link OwnerMapper#toIdentityKey}.
570	     *
571	     * @param owner the incoming owner, with its normalized telephone, email and household identifier
572	     *              already populated
573	     * @throws DuplicateIdentityException if another owner already has this exact identity key
574	     */
575	    private void requireUniqueIdentity(Owner owner) {
576	        String identityKey = ownerMapper.toIdentityKey(owner);
577	        boolean taken = this.clinicService.findAllOwners().stream()
578	            .map(ownerMapper::toIdentityKey)
579	            .anyMatch(identityKey::equals);
580	        if (taken) {
581	            throw new DuplicateIdentityException(identityKey);
582	        }
583	    }
584	
585	    /**
586	     * Rejects the request when the incoming owner would join an existing household, unless the owner
587	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
588	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
589	     * same {@code householdId} is a member of the same household, so a second such owner is a
590	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
591	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
592	     * so no household key) is never a household duplicate.
593	     *
594	     * @param owner the incoming owner, with its computed {@code householdId} already populated
595	     * @param sharesHousehold whether the request opted in to joining an existing household
596	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
597	     */
598	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
599	        if (sharesHousehold) {
600	            return;
601	        }
602	        String householdId = owner.getHouseholdId();
603	        if (householdId == null) {
604	            return;
605	        }
606	        boolean householdExists = this.clinicService.findAllOwners().stream()
607	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
608	        if (householdExists) {
609	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
610	        }
611	    }
612	
613	    /**
614	     * Flags the incoming owner as a possible (soft) duplicate. Called after the hard-duplicate and
615	     * household-duplicate checks have passed, so the owner is known not to be a rejected duplicate.
616	     * When an existing owner shares this owner's household (same computed {@code householdId}) but
617	     * carries a different telephone, the owner is a possible duplicate: {@code possibleDuplicate} is
618	     * set {@code true} and {@code possibleDuplicateOf} to that existing owner's id (the earliest such
619	     * owner by id when more than one matches). Otherwise both are cleared. A declared household member
620	     * ({@code sharesHousehold} true) is never flagged: it is a deliberate member, not a suspected
621	     * duplicate. An owner with no {@code householdId} never matches, since it shares no household.
622	     *
623	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
624	     * @param sharesHousehold whether the request opted in as a declared household member
625	     */
626	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
627	        owner.setPossibleDuplicate(false);
628	        owner.setPossibleDuplicateOf(null);
629	        if (sharesHousehold) {
630	            return;
631	        }
632	        String householdId = owner.getHouseholdId();
633	        if (householdId == null) {
634	            return;
635	        }
636	        String telephone = owner.getTelephone();
637	        this.clinicService.findAllOwners().stream()
638	            .filter(existing -> householdId.equals(existing.getHouseholdId())
639	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
640	            .min(java.util.Comparator.comparing(Owner::getId))
641	            .ifPresent(match -> {
642	                owner.setPossibleDuplicate(true);
643	                owner.setPossibleDuplicateOf(match.getId());
644	            });
645	    }
646	
647	    /**
648	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
649	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
650	     * comparisons are case-insensitive.
651	     */
652	    private static String normalizeForHousehold(String value) {
653	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
654	    }
655	
656	    /**
657	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
658	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
659	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
660	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
661	     * value normalizes to the empty string, so the required-field check rejects an address that is
662	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
663	     *
664	     * @param address the raw address value from the request (may be {@code null})
665	     * @return the normalized address, or the empty string when blank after normalization
666	     */
667	    private static String normalizeAddress(String address) {
668	        if (address == null) {
669	            return "";
670	        }
671	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
672	        if (collapsed.isEmpty()) {
673	            return "";
674	        }
675	        String[] tokens = collapsed.split(" ");
676	        StringBuilder sb = new StringBuilder();
677	        for (String token : tokens) {
678	            String expanded = switch (token) {
679	                case "ST" -> "STREET";
680	                case "RD" -> "ROAD";
681	                case "AVE" -> "AVENUE";
682	                default -> token;
683	            };
684	            if (sb.length() > 0) {
685	                sb.append(' ');
686	            }
687	            sb.append(expanded);
688	        }
689	        return sb.toString();
690	    }
691	
692	    /**
693	     * Derives the stable household identifier for an owner from its last name and postcode as the
694	     * upper-cased first 12 hex characters of the SHA-256 digest of
695	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
696	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
697	     * identifier is a deterministic function of the normalized last name and postcode, owners that
698	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
699	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
700	     * postcode and there is then nothing to key on.
701	     *
702	     * @param lastName the owner's last name (already validated non-blank)
703	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
704	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
705	     */
706	    private static String householdIdFor(String lastName, String postcode) {
707	        if (postcode == null || postcode.isBlank()) {
708	            return null;
709	        }
710	        String normalizedLastName = normalizeForHousehold(lastName);
711	        try {
712	            byte[] digest = MessageDigest.getInstance("SHA-256")
713	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
714	            StringBuilder sb = new StringBuilder();
715	            for (byte b : digest) {
716	                sb.append(String.format("%02X", b));
717	            }
718	            return sb.substring(0, 12);
719	        }
720	        catch (NoSuchAlgorithmException e) {
721	            throw new IllegalStateException("SHA-256 not available", e);
722	        }
723	    }
724	}
